Vehicle['vehicle_type'] === $type ? 'selected' : '' ?>><?= e($type) ?></option><?php endforeach; ?></select></label></div><div class="col-6"><label class="form-label">Model *<input class="form-control" name="register_vehicle[model]" value="<?= e($registerVehicle['model']) ?>" placeholder="Vehicle model"></label></div></div><label class="form-label">Make / Brand<input class="form-control" name="register_vehicle[make]" value="<?= e($registerVehicle['make']) ?>" placeholder="Optional"></label><label class="form-check"><input class="form-check-input" type="checkbox" name="register_new_vehicle" value="1" <?= $registerVehicle['enabled'] ? 'checked' : '' ?>> Save this vehicle to the customer profile</label></div></div><div class="col-4"><label class="form-label">Mileage (KM)</label><input class="form-control" type="number" step="0.01" name="mileage" id="estimate-mileage" value="<?= e($input['mileage']) ?>" placeholder="Enter mileage"></div><div class="col-4"><label class="form-label">Engine No.</label><input class="form-control" name="engine_number" id="estimate-engine-number" value="<?= e($input['engine_number']) ?>" placeholder="Engine no."></div><div class="col-4"><label class="form-label">Chassis No.</label><input class="form-control" name="chassis_number" id="estimate-chassis-number" value="<?= e($input['chassis_number']) ?>" placeholder="Chassis no."></div></div></section>
<section class="estimate-form-section"><h3>Estimate Details</h3><div class="row g-3"><div class="col-6"><label class="form-label">Estimate Date *</label><input class="form-control" type="date" name="estimate_date" value="<?= e($input['estimate_date']) ?>" required></div><div class="col-6"><label class="form-label">Valid Until *</label><input class="form-control" type="date" name="valid_until" value="<?= e($input['valid_until']) ?>" required></div><div class="col-8"><label class="form-label">Service Type / Issue *</label><input class="form-control" name="service_type" value="<?= e($input['service_type']) ?>" placeholder="Select or enter service type" required></div><div class="col-4"><label class="form-label">Status</label><select class="form-select" name="status"><?php foreach ($statusLabels as $value => $label): ?><option value="<?= e($value) ?>" <?= $input['status'] === $value ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></div><div class="col-12"><label class="form-label">Notes</label><textarea class="form-control" name="notes" rows="2" maxlength="250" placeholder="Add any notes about the estimate..."><?= e($input['notes']) ?></textarea></div></div></section>
<section class="estimate-form-section"><div class="estimate-items-heading"><h3>Estimate Items</h3><button type="button" class="btn btn-outline-danger btn-sm" id="add-estimate-item">+ Add Item</button></div><div id="estimate-items"><?php foreach ($input['items'] as $index => $item): ?><div class="estimate-item-row"><input class="form-control" name="items[<?= $index ?>][name]" value="<?= e($item['name']) ?>" placeholder="Item / Service" required><input class="form-control estimate-qty" type="number" min="0.01" step="0.01" name="items[<?= $index ?>][quantity]" value="<?= e($item['quantity']) ?>"><input class="form-control estimate-price" type="number" min="0" step="0.01" name="items[<?= $index ?>][unit_price]" value="<?= e($item['unit_price']) ?>"><output class="estimate-line-amount">0.00</output><button type="button" class="estimate-remove-item" title="Remove item">&times;</button></div><?php endforeach; ?></div></section>
<section class="estimate-total-box"><div><span>Sub Total</span><strong id="estimate-subtotal">Rs. 0.00</strong></div><div><label>Discount <input class="form-control" id="estimate-discount" type="number" min="0" step="0.01" name="discount" value="<?= e($input['discount']) ?>"></label><strong id="estimate-discount-display">Rs. 0.00</strong></div><div><label>VAT (%) <input class="form-control" id="estimate-vat-rate" type="number" min="0" step="0.01" name="vat_rate" value="<?= e($input['vat_rate']) ?>"></label><strong id="estimate-vat-display">Rs. 0.00</strong></div><div class="estimate-grand-total"><span>Total Amount</span><strong id="estimate-total">Rs. 0.00</strong></div></section><div class="estimate-form-footer"><a class="btn btn-light" href="index.php?page=admin&amp;section=estimates">Cancel</a><button class="btn btn-danger" type="submit">Save Estimate</button></div></form></div></section></div>
