<datalist id="estimate-catalog-options"><?php foreach ($catalog as $entry): ?><option value="<?= e($entry['name']) ?>" data-price="<?= e((string) $entry['price']) ?>"><?= e($entry['kind']) ?></option><?php endforeach; ?></datalist>
<script>
document.addEventListener('DOMContentLoaded',function(){const items=document.getElementById('estimate-items'),add=document.getElementById('add-estimate-item'),customer=document.getElementById('estimate-customer'),vehicle=document.getElementById('estimate-vehicle'),registerPanel=document.getElementById('register-vehicle-panel'),registerToggle=document.getElementById('toggle-register-vehicle'),mileage=document.getElementById('estimate-mileage'),engine=document.getElementById('estimate-engine-number'),chassis=document.getElementById('estimate-chassis-number');let next=items.querySelectorAll('.estimate-item-row').length;function filterVehicles(){Array.from(vehicle.options).forEach(function(o){if(!o.dataset.customerId)return;o.hidden=!!customer.value&&o.dataset.customerId!==customer.value;if(o.hidden&&o.selected)vehicle.value='0';});}function fillVehicle(force){const o=vehicle.options[vehicle.selectedIndex];if(!o||!o.value)return;if(force||!mileage.value)mileage.value=o.dataset.mileage||'';if(force||!engine.value)engine.value=o.dataset.engineNumber||'';if(force||!chassis.value)chassis.value=o.dataset.chassisNumber||'';}function totals(){let sub=0;items.querySelectorAll('.estimate-item-row').forEach(function(row){const q=parseFloat(row.querySelector('.estimate-qty').value)||0,p=parseFloat(row.querySelector('.estimate-price').value)||0,a=q*p;row.querySelector('.estimate-line-amount').textContent=a.toFixed(2);sub+=a;});const discount=Math.min(parseFloat(document.getElementById('estimate-discount').value)||0,sub),rate=parseFloat(document.getElementById('estimate-vat-rate').value)||0,vat=(sub-discount)*rate/100;document.getElementById('estimate-subtotal').textContent='Rs. '+sub.toFixed(2);document.getElementById('estimate-discount-display').textContent='Rs. '+discount.toFixed(2);document.getElementById('estimate-vat-display').textContent='Rs. '+vat.toFixed(2);document.getElementById('estimate-total').textContent='Rs. '+(sub-discount+vat).toFixed(2);}function bind(row){row.querySelectorAll('input').forEach(function(i){i.addEventListener('input',totals);});row.querySelector('.estimate-remove-item').addEventListener('click',function(){row.remove();totals();});}add.addEventListener('click',function(){const row=document.createElement('div');row.className='estimate-item-row';row.innerHTML='<input class="form-control" name="items['+next+'][name]" placeholder="Item / Service" required><input class="form-control estimate-qty" type="number" min="0.01" step="0.01" name="items['+next+'][quantity]" value="1"><input class="form-control estimate-price" type="number" min="0" step="0.01" name="items['+next+'][unit_price]" value="0"><output class="estimate-line-amount">0.00</output><button type="button" class="estimate-remove-item">&times;</button>';items.appendChild(row);bind(row);next++;});registerToggle.addEventListener('click',function(){if(registerPanel.hasAttribute('hidden'))registerPanel.removeAttribute('hidden');else registerPanel.setAttribute('hidden','');});customer.addEventListener('change',function(){filterVehicles();if(vehicle.value==='0'){mileage.value='';engine.value='';chassis.value='';}});vehicle.addEventListener('change',function(){fillVehicle(true);});items.querySelectorAll('.estimate-item-row').forEach(bind);document.getElementById('estimate-discount').addEventListener('input',totals);document.getElementById('estimate-vat-rate').addEventListener('input',totals);filterVehicles();fillVehicle(false);totals();});
</script>
<script>
document.addEventListener('DOMContentLoaded', function () {
    const serviceBox = document.querySelector('.estimate-service-charge');
    const totalBox = document.querySelector('.estimate-total-box');
    if (serviceBox && totalBox) totalBox.parentNode.insertBefore(serviceBox, totalBox);
});
</script>
<script>
document.addEventListener('DOMContentLoaded', function () {
    const items = document.getElementById('estimate-items'), service = document.getElementById('estimate-service-charge'), discount = document.getElementById('estimate-discount'), vatRate = document.getElementById('estimate-vat-rate');
    function recalculateWithService() { let itemTotal = 0; items.querySelectorAll('.estimate-item-row').forEach(function (row) { itemTotal += (parseFloat(row.querySelector('.estimate-qty').value) || 0) * (parseFloat(row.querySelector('.estimate-price').value) || 0); }); const subtotal = itemTotal + (parseFloat(service.value) || 0), discountValue = Math.min(parseFloat(discount.value) || 0, subtotal), vat = (subtotal - discountValue) * (parseFloat(vatRate.value) || 0) / 100; document.getElementById('estimate-subtotal').textContent = 'Rs. ' + subtotal.toFixed(2); document.getElementById('estimate-discount-display').textContent = 'Rs. ' + discountValue.toFixed(2); document.getElementById('estimate-vat-display').textContent = 'Rs. ' + vat.toFixed(2); document.getElementById('estimate-total').textContent = 'Rs. ' + (subtotal - discountValue + vat).toFixed(2); }
    service.addEventListener('input', recalculateWithService); discount.addEventListener('input', recalculateWithService); vatRate.addEventListener('input', recalculateWithService); items.addEventListener('input', recalculateWithService); recalculateWithService();
});
</script>
<script>
document.addEventListener('DOMContentLoaded', function () {
    const catalog = Array.from(document.querySelectorAll('#estimate-catalog-options option')).map(function (option) { return { name: option.value.toLowerCase(), price: parseFloat(option.dataset.price || '0') || 0 }; });
    const items = document.getElementById('estimate-items');
    function enhance(row) { const name = row.querySelector('input[name*="[name]"]'), price = row.querySelector('.estimate-price'); if (!name || name.dataset.catalogReady) return; name.dataset.catalogReady = '1'; name.setAttribute('list', 'estimate-catalog-options'); name.placeholder = 'Search spare part or garage service'; name.addEventListener('change', function () { const match = catalog.find(function (entry) { return entry.name === name.value.trim().toLowerCase(); }); if (match && match.price > 0) { price.value = match.price.toFixed(2); price.dispatchEvent(new Event('input', { bubbles: true })); } }); }
    items.querySelectorAll('.estimate-item-row').forEach(enhance); new MutationObserver(function (records) { records.forEach(function (record) { record.addedNodes.forEach(function (node) { if (node.nodeType === 1) enhance(node); }); }); }).observe(items, { childList: true });
});
</script>
